package com.turboio.addon;

import android.app.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Daily reading surface for real, account-verified retained materials. */
final class AgentMaterialPage {
 private final Activity activity;private final MaterialRuntime runtime;private final ScrollView scroll;private final LinearLayout body;
 private final List<Dialog> dialogs=new ArrayList<>(),sensitiveDialogs=new ArrayList<>();private final List<AgentUI.Screen> syncScreens=new ArrayList<>();private MaterialRuntime.CatalogSnapshot snapshot;
 private final Application.ActivityLifecycleCallbacks lifecycle;private final boolean browsing;private boolean suspended,active;
 private LocalDate selected=LocalDate.now();private boolean closed,openingDelegate,reading;private String readError="";private long revision,syncRevision,readOwner=-1;
 AgentMaterialPage(Activity activity){this(activity,true);}
 private AgentMaterialPage(Activity activity,boolean load){this.activity=activity;browsing=load;runtime=MaterialRuntime.get(activity);body=AgentUI.column(activity);body.setPadding(AgentUI.dp(activity,20),AgentUI.dp(activity,16),AgentUI.dp(activity,20),AgentUI.dp(activity,24));scroll=new ScrollView(activity);scroll.setFillViewport(true);scroll.addView(body);
  lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityStopped(Activity a){if(a==activity&&!closed){suspended=true;revision++;syncRevision++;reading=false;invalidateContent("返回后将重新核对账号…");for(AgentUI.Screen screen:new ArrayList<>(syncScreens))if(screen.dialog.isShowing()){screen.body.removeAllViews();screen.body.addView(AgentUI.text(activity,"返回后将重新核对资料连接…",14,AgentUI.MUTED));}}}public void onActivityResumed(Activity a){if(a==activity&&!closed&&suspended){suspended=false;if(browsing&&active&&syncScreens.isEmpty())refresh();for(AgentUI.Screen screen:new ArrayList<>(syncScreens))if(screen.dialog.isShowing())reloadSync(screen);}}public void onActivityDestroyed(Activity a){if(a==activity)close();}public void onActivityCreated(Activity a,android.os.Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivitySaveInstanceState(Activity a,android.os.Bundle b){}};
  activity.getApplication().registerActivityLifecycleCallbacks(lifecycle);}
 static void settings(Activity activity){AgentMaterialPage page=new AgentMaterialPage(activity,false);AgentUI.Screen screen=new AgentUI.Screen(activity,"资料同步");page.trackSync(screen);screen.dialog.setOnDismissListener(d->{page.dialogs.remove(screen.dialog);page.close();});screen.body.addView(AgentUI.text(activity,"正在读取同步设置…",14,AgentUI.MUTED));page.reloadSync(screen);}
 View view(){return scroll;}
 void setActive(boolean value){if(active==value)return;active=value;if(!value){revision++;reading=false;if(readOwner>=0)runtime.cancelRead(readOwner);}}
 void close(){if(closed)return;closed=true;revision++;syncRevision++;if(readOwner>=0)runtime.cancelRead(readOwner);activity.getApplication().unregisterActivityLifecycleCallbacks(lifecycle);for(Dialog dialog:new ArrayList<>(dialogs))if(dialog.isShowing())dialog.dismiss();dialogs.clear();snapshot=null;}
 void refresh(){if(closed||suspended||!browsing||!active||activity.isDestroyed())return;long request=++revision;body.removeAllViews();heading();body.addView(AgentUI.text(activity,"正在读取已保存资料…",14,AgentUI.MUTED));runtime.catalog((value,error)->{
  if(closed||suspended||request!=revision||activity.isDestroyed())return;if(!error.isEmpty()){invalidateContent(MaterialWorkspace.label(error));return;}snapshot=value;render();readSelected();
 });}
 private void select(LocalDate day){selected=day;readError="";readSelected();}
 private void readSelected(){if(closed||suspended||!active||snapshot==null)return;final LocalDate day=selected;final String timezone=snapshot.catalog.zone.getId();long request=++revision;reading=true;readError="";render();
  readOwner=runtime.readDay(day.toString(),timezone,(value,error)->{if(closed||suspended||request!=revision||activity.isDestroyed())return;reading=false;
   if(value==null){invalidateContent(MaterialWorkspace.label(error));return;}snapshot=value;readError=error;render();
  });
 }
 private MaterialLocalLibrary.DayRead dayRead(){return snapshot==null||snapshot.local==null?null:snapshot.local.day(selected.toString(),snapshot.catalog.zone.getId());}
 private String readMessage(){if(reading)return "正在从原厂读取这一天的智记…";if(!readError.isEmpty())return "本次读取未完成："+MaterialWorkspace.label(readError)+"。已读取内容保留。";MaterialLocalLibrary.DayRead read=dayRead();return read==null?"尚未读取这一天的原厂智记":"原厂读取于 "+stamp(read.readAt)+" · 本次返回 "+read.sourceCount+" 份正文";}
 private void heading(){body.addView(AgentUI.text(activity,"资料",28,AgentUI.INK));AgentUI.gap(activity,body,6);body.addView(AgentUI.text(activity,"按日期查看你的记录。",14,AgentUI.MUTED));AgentUI.gap(activity,body,12);}
 private void render(){if(closed||snapshot==null)return;body.removeAllViews();heading();MaterialCatalog catalog=snapshot.catalog;MaterialConfig config=snapshot.config;
  LinearLayout status=AgentUI.card(activity,body);String label=config==null?"尚未连接资料空间":!config.enabled?"资料同步已关闭":config.connection.expiresAt<=System.currentTimeMillis()?"资料连接已到期":"资料连接已开启";
  status.addView(AgentUI.text(activity,"原厂智记",17,AgentUI.INK));status.addView(AgentUI.text(activity,"打开页面、切换日期时自动读取",12,AgentUI.MUTED));status.addView(AgentUI.text(activity,(snapshot.uploadError.isEmpty()?label:"同步状态需处理")+" · 不影响本机读取",12,AgentUI.MUTED));AgentUI.gap(activity,status,12);
  LinearLayout counts=new LinearLayout(activity);count(counts,Integer.toString(catalog.entries.size()),"本机可读");count(counts,Integer.toString(catalog.stored),"已同步文字");count(counts,Integer.toString(catalog.pending),"待同步");status.addView(counts);AgentUI.button(activity,status,"查看同步详情",false,this::syncDetails);
  AgentUI.gap(activity,body,18);LinearLayout dateHeading=new LinearLayout(activity);dateHeading.setGravity(Gravity.CENTER_VERTICAL);TextView month=AgentUI.text(activity,selected.getYear()+" 年 "+selected.getMonthValue()+" 月",17,AgentUI.INK);dateHeading.addView(month,new LinearLayout.LayoutParams(0,-2,1));TextView choose=AgentUI.text(activity,"选择日期",14,AgentUI.ACCENT);choose.setPadding(AgentUI.dp(activity,8),AgentUI.dp(activity,12),0,AgentUI.dp(activity,12));choose.setOnClickListener(v->calendar());choose.setFocusable(true);dateHeading.addView(choose);body.addView(dateHeading);
  LinearLayout week=new LinearLayout(activity);LocalDate start=selected.minusDays(selected.getDayOfWeek().getValue()-1L);for(int i=0;i<7;i++){LocalDate day=start.plusDays(i);LinearLayout cell=AgentUI.column(activity);cell.setGravity(Gravity.CENTER);cell.setPadding(0,AgentUI.dp(activity,8),0,AgentUI.dp(activity,8));TextView weekday=AgentUI.text(activity,new String[]{"一","二","三","四","五","六","日"}[i],11,AgentUI.MUTED);weekday.setGravity(Gravity.CENTER);cell.addView(weekday);TextView number=AgentUI.text(activity,Integer.toString(day.getDayOfMonth()),15,day.equals(selected)?AgentUI.ACCENT:AgentUI.INK);number.setGravity(Gravity.CENTER);cell.addView(number);TextView dot=AgentUI.text(activity,catalog.dates.contains(day)?"•":" ",12,AgentUI.ACCENT);dot.setGravity(Gravity.CENTER);cell.addView(dot);if(day.equals(selected))cell.setBackground(shape(0xff203d30,14));cell.setContentDescription(day+(catalog.dates.contains(day)?"，有已保存记录":"，无已保存记录"));cell.setFocusable(true);cell.setOnClickListener(v->select(day));week.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}body.addView(week);
  AgentUI.gap(activity,body,18);List<MaterialCatalog.Entry> entries=catalog.on(selected);body.addView(AgentUI.text(activity,(selected.equals(LocalDate.now(catalog.zone))?"今天":selected.toString())+"  ·  "+entries.size()+" 条记录",16,AgentUI.INK));body.addView(AgentUI.text(activity,readMessage(),12,AgentUI.MUTED));TextView reload=AgentUI.button(activity,body,reading?"正在读取…":"刷新当天智记",false,this::readSelected);reload.setEnabled(!reading);
  if(entries.isEmpty()){LinearLayout empty=AgentUI.card(activity,body);empty.addView(AgentUI.text(activity,reading?"正在检查原厂记录":!readError.isEmpty()?"暂时无法取得当天记录":dayRead()==null?"这一天尚未读取":"原厂暂未返回可读取的智记正文",16,AgentUI.INK));empty.addView(AgentUI.text(activity,"全天智记开启不代表正文已生成；生成后可刷新读取。读取失败不会清除已有内容。",13,AgentUI.MUTED));}
  for(MaterialCatalog.Entry entry:entries){LinearLayout card=AgentUI.card(activity,body);TextView title=AgentUI.text(activity,entry.title+"  ›",17,AgentUI.INK);title.setTypeface(null,Typeface.BOLD);card.addView(title);AgentUI.gap(activity,card,5);card.addView(AgentUI.text(activity,entry.timeRange()+" · "+Math.max(1,(entry.endedAt-entry.startedAt+59999)/60000)+" 分钟",12,AgentUI.MUTED));AgentUI.gap(activity,card,8);card.addView(AgentUI.text(activity,entry.syncLabel(),13,"server_stored".equals(entry.state)?AgentUI.ACCENT:AgentUI.MUTED));card.setFocusable(true);card.setContentDescription(entry.title+"，"+entry.syncLabel());card.setOnClickListener(v->open(entry));}
  AgentUI.gap(activity,body,16);body.addView(AgentUI.text(activity,"日期按手机时区读取："+catalog.zone.getId()+"\n原厂读取保存在本机；上传到资料空间是独立操作。",11,AgentUI.MUTED));
 }
 private void count(LinearLayout parent,String number,String label){LinearLayout column=AgentUI.column(activity);column.addView(AgentUI.text(activity,number,23,AgentUI.INK));column.addView(AgentUI.text(activity,label,11,AgentUI.MUTED));parent.addView(column,new LinearLayout.LayoutParams(0,-2,1));}
 private GradientDrawable shape(int color,int radius){GradientDrawable shape=new GradientDrawable();shape.setColor(color);shape.setCornerRadius(AgentUI.dp(activity,radius));return shape;}
 private String stamp(long time){return DateTimeFormatter.ofPattern("MM-dd HH:mm",Locale.CHINA).format(Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()));}
 private void track(Dialog dialog){dialogs.add(dialog);dialog.setOnDismissListener(d->{dialogs.remove(dialog);sensitiveDialogs.remove(dialog);syncScreens.removeIf(screen->screen.dialog==dialog);});}
 private void trackSensitive(Dialog dialog){track(dialog);sensitiveDialogs.add(dialog);}
 private void trackSync(AgentUI.Screen screen){track(screen.dialog);syncScreens.add(screen);screen.dialog.setOnDismissListener(d->{dialogs.remove(screen.dialog);syncScreens.remove(screen);if(!closed&&!suspended&&browsing)refresh();});}
 private void invalidateContent(String message){snapshot=null;for(Dialog dialog:new ArrayList<>(sensitiveDialogs))if(dialog.isShowing())dialog.dismiss();sensitiveDialogs.clear();body.removeAllViews();heading();body.addView(AgentUI.text(activity,message,15,AgentUI.MUTED));if(!suspended)AgentUI.button(activity,body,"重新验证资料",false,this::refresh);}
 private void syncDetails(){if(snapshot==null)return;if(reading){revision++;reading=false;if(readOwner>=0)runtime.cancelRead(readOwner);}AgentUI.Screen screen=new AgentUI.Screen(activity,"资料同步");trackSync(screen);renderSync(screen);}
 private void renderSync(AgentUI.Screen screen){screen.body.removeAllViews();if(snapshot==null)return;MaterialConfig config=snapshot.config;MaterialCatalog catalog=snapshot.catalog;
  if(!snapshot.uploadError.isEmpty())screen.body.addView(AgentUI.text(activity,"上传记录暂时无法读取："+MaterialWorkspace.label(snapshot.uploadError)+"。本机智记仍可阅读。",14,AgentUI.MUTED));
  screen.body.addView(AgentUI.text(activity,config!=null&&config.enabled?"资料连接已开启":"资料连接未开启",22,AgentUI.INK));AgentUI.gap(activity,screen.body,8);screen.body.addView(AgentUI.text(activity,"原厂智记在资料页按日期自动读取并保存在本机。上传到电脑资料空间仍由你手动同步；成功时间以服务器确认保存为准。",14,AgentUI.MUTED));
  if(config!=null){LinearLayout card=AgentUI.card(activity,screen.body);card.addView(AgentUI.text(activity,"允许资料同步",16,AgentUI.INK));card.addView(AgentUI.text(activity,"关闭后停止本次上传，保留已保存正文和待同步队列。",13,AgentUI.MUTED));Switch toggle=new Switch(new android.view.ContextThemeWrapper(activity,android.R.style.Theme_Material_NoActionBar));toggle.setTrackTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{AgentUI.ACCENT,0xff58645c}));toggle.setThumbTintList(android.content.res.ColorStateList.valueOf(AgentUI.INK));toggle.setText(config.enabled?"已开启":"已关闭");toggle.setTextColor(AgentUI.INK);toggle.setContentDescription("允许资料同步");toggle.setChecked(config.enabled);card.addView(toggle,new LinearLayout.LayoutParams(-1,AgentUI.dp(activity,48)));toggle.setOnCheckedChangeListener((button,on)->{toggle.setEnabled(false);MaterialRuntime.Result done=(state,error)->{if(closed||!screen.dialog.isShowing())return;if(!error.isEmpty())AgentUI.notice(activity,MaterialWorkspace.label(error));reloadSync(screen);};runtime.setEnabled(config.fingerprint(),on,done);});
   AgentUI.gap(activity,screen.body,16);screen.body.addView(AgentUI.text(activity,catalog.lastStoredAt>0?"最近上传成功："+stamp(catalog.lastStoredAt):"尚无上传成功记录",14,AgentUI.MUTED));screen.body.addView(AgentUI.text(activity,"已同步 "+catalog.stored+" 条 · 待同步 "+catalog.pending+" 条 · 需处理 "+catalog.attention+" 条",14,AgentUI.INK));
   if(config.connection.expiresAt<=System.currentTimeMillis())screen.body.addView(AgentUI.text(activity,"远程连接已到期。仍可读取新的原厂智记并导出；更新连接后才能继续上传。",14,AgentUI.MUTED));
   TextView[] sync={null};sync[0]=AgentUI.button(activity,screen.body,"上传所选日期的智记",true,()->{sync[0].setEnabled(false);sync[0].setText("正在同步…");runtime.syncDay(selected.toString(),catalog.zone.getId(),(state,error)->{if(closed||!screen.dialog.isShowing())return;if(!error.isEmpty())AgentUI.notice(activity,MaterialWorkspace.label(error));reloadSync(screen);});});sync[0].setEnabled(snapshot.uploadError.isEmpty()&&config.enabled&&config.connection.expiresAt>System.currentTimeMillis());sync[0].setAlpha(sync[0].isEnabled()?1f:.45f);
   TextView month=AgentUI.button(activity,screen.body,"按月份选择并上传",false,()->MaterialMonthWorkspace.show(activity,runtime,config,()->!closed&&screen.dialog.isShowing(),()->screen.body.addView(AgentUI.text(activity,"正在查找智记…",14,AgentUI.MUTED)),()->reloadSync(screen)));month.setEnabled(snapshot.uploadError.isEmpty()&&config.enabled&&config.connection.expiresAt>System.currentTimeMillis());month.setAlpha(month.isEnabled()?1f:.45f);
  }
  AgentUI.button(activity,screen.body,"资料连接设置",false,()->MaterialWorkspace.show(activity,()->{if(!closed&&!suspended&&screen.dialog.isShowing())reloadSync(screen);}));AgentUI.button(activity,screen.body,"刷新状态",false,()->reloadSync(screen));AgentUI.gap(activity,screen.body,18);screen.body.addView(AgentUI.text(activity,"远程原音保存与自动同步仍在接入。已有文字同步不代表原音已备份。",13,AgentUI.MUTED));
 }
 private void reloadSync(AgentUI.Screen screen){if(closed||suspended)return;long request=++syncRevision;runtime.catalog((value,error)->{if(closed||suspended||request!=syncRevision||!screen.dialog.isShowing())return;if(!error.isEmpty()){invalidateContent(MaterialWorkspace.label(error));screen.body.removeAllViews();screen.body.addView(AgentUI.text(activity,MaterialWorkspace.label(error),16,AgentUI.MUTED));AgentUI.button(activity,screen.body,"重新读取",false,()->reloadSync(screen));return;}snapshot=value;if(browsing)render();renderSync(screen);});}
 private void calendar(){if(snapshot==null)return;MaterialCatalog catalog=snapshot.catalog;YearMonth[] shown={YearMonth.from(selected)};LinearLayout layout=AgentUI.column(activity);layout.setPadding(AgentUI.dp(activity,12),AgentUI.dp(activity,12),AgentUI.dp(activity,12),AgentUI.dp(activity,16));layout.setBackgroundColor(AgentUI.SURFACE);AlertDialog dialog=AgentUI.alert(activity).setView(layout).setNegativeButton("返回",null).create();Runnable[] draw={null};draw[0]=()->{
  layout.removeAllViews();LinearLayout controls=new LinearLayout(activity);String[] labels={"‹",shown[0].getYear()+" 年 "+shown[0].getMonthValue()+" 月","›"};for(int i=0;i<3;i++){final int action=i;TextView label=AgentUI.text(activity,labels[i],i==1?17:26,AgentUI.INK);label.setGravity(Gravity.CENTER);controls.addView(label,new LinearLayout.LayoutParams(0,AgentUI.dp(activity,48),i==1?4:1));if(i!=1){label.setContentDescription(i==0?"上个月":"下个月");label.setFocusable(true);label.setOnClickListener(v->{shown[0]=shown[0].plusMonths(action==0?-1:1);draw[0].run();});}}layout.addView(controls);
  LinearLayout weekdays=new LinearLayout(activity);for(String day:new String[]{"一","二","三","四","五","六","日"}){TextView label=AgentUI.text(activity,day,12,AgentUI.MUTED);label.setGravity(Gravity.CENTER);weekdays.addView(label,new LinearLayout.LayoutParams(0,AgentUI.dp(activity,32),1));}layout.addView(weekdays);
  int offset=shown[0].atDay(1).getDayOfWeek().getValue()-1;for(int row=0;row<6;row++){LinearLayout week=new LinearLayout(activity);for(int col=0;col<7;col++){int day=row*7+col-offset+1;TextView label=AgentUI.text(activity,"",14,AgentUI.INK);label.setGravity(Gravity.CENTER);week.addView(label,new LinearLayout.LayoutParams(0,AgentUI.dp(activity,46),1));if(day>=1&&day<=shown[0].lengthOfMonth()){LocalDate date=shown[0].atDay(day);boolean exists=catalog.dates.contains(date);label.setText(day+"\n"+(exists?"•":" "));if(date.equals(selected)){label.setBackground(shape(0xff203d30,12));label.setTextColor(AgentUI.ACCENT);}label.setContentDescription(date+(exists?"，有已保存记录":"，无已保存记录"));label.setFocusable(true);label.setOnClickListener(v->{dialog.dismiss();select(date);});}}layout.addView(week);}
  AgentUI.gap(activity,layout,8);layout.addView(AgentUI.text(activity,"• 有已保存记录 · 日期按手机时区显示",12,AgentUI.MUTED));
 };draw[0].run();dialog.show();trackSensitive(dialog);}
 private void open(MaterialCatalog.Entry selectedEntry){if(snapshot==null||suspended)return;long request=revision;String owner=snapshot.catalog.account;runtime.catalog((value,error)->{
  if(closed||suspended||request!=revision||activity.isDestroyed())return;if(!error.isEmpty()||value==null||!owner.equals(value.catalog.account)){AgentUI.notice(activity,error.isEmpty()?"账号已变化，请重新读取资料。":MaterialWorkspace.label(error));refresh();return;}
  for(MaterialCatalog.Entry current:value.catalog.entries)if(current.id.equals(selectedEntry.id)){detail(value.catalog,current);return;}AgentUI.notice(activity,"这条记录已不在当前资料列表中，请刷新后查看。");refresh();
 });}
 private void detail(MaterialCatalog catalog,MaterialCatalog.Entry entry){AgentUI.Screen screen=new AgentUI.Screen(activity,"智记详情");trackSensitive(screen.dialog);screen.body.addView(AgentUI.text(activity,entry.title,23,AgentUI.INK));screen.body.addView(AgentUI.text(activity,entry.day+" · "+entry.timeRange()+" · "+entry.zone.getId(),12,AgentUI.MUTED));AgentUI.gap(activity,screen.body,8);screen.body.addView(AgentUI.text(activity,entry.syncLabel()+" · "+entry.coverage,13,AgentUI.MUTED));
  AgentUI.button(activity,screen.body,"导出文档到手机",false,()->export(catalog,entry));
  LinearLayout audio=AgentUI.card(activity,screen.body);audio.addView(AgentUI.text(activity,"原音",17,AgentUI.INK));audio.addView(AgentUI.text(activity,"暂无可导出的原音",14,AgentUI.MUTED));audio.addView(AgentUI.text(activity,"这条记录未关联可验证的原音文件。文字可独立导出。",12,AgentUI.MUTED));TextView audioExport=AgentUI.button(activity,audio,"导出原音",false,()->{});audioExport.setEnabled(false);audioExport.setAlpha(.45f);audioExport.setContentDescription("导出原音不可用：这条记录未关联可验证的原音文件");
  LinearLayout content=AgentUI.card(activity,screen.body);content.addView(AgentUI.text(activity,"转写正文",18,AgentUI.INK));AgentUI.gap(activity,content,10);TextView full=AgentUI.text(activity,entry.fullText.isEmpty()?"暂无转写正文":entry.fullText,16,AgentUI.INK);full.setTextIsSelectable(true);content.addView(full);
  if(!entry.segments.isEmpty()){LinearLayout segments=AgentUI.card(activity,screen.body);segments.addView(AgentUI.text(activity,"原文片段",18,AgentUI.INK));segments.addView(AgentUI.text(activity,"时间相对记录开头；说话人沿用原记录标签。",12,AgentUI.MUTED));final int[] shown={0};final TextView[] more={null};Runnable[] append={null};append[0]=()->{if(more[0]!=null)segments.removeView(more[0]);int end=Math.min(shown[0]+40,entry.segments.size());for(;shown[0]<end;shown[0]++){MaterialCatalog.Segment segment=entry.segments.get(shown[0]);AgentUI.gap(activity,segments,14);segments.addView(AgentUI.text(activity,MaterialDocument.segmentTime(segment)+" · "+segment.speaker,12,AgentUI.MUTED));TextView text=AgentUI.text(activity,segment.text,16,AgentUI.INK);text.setTextIsSelectable(true);segments.addView(text);}if(shown[0]<entry.segments.size())more[0]=AgentUI.button(activity,segments,"继续查看原文（还有 "+(entry.segments.size()-shown[0])+" 段）",false,append[0]);};append[0].run();}
  AgentUI.button(activity,screen.dock,"基于这份资料委托任务",true,()->delegate(catalog,entry,screen));AgentUI.gap(activity,screen.body,16);screen.body.addView(AgentUI.text(activity,"导出保留正文、说话人标签和时间；不改动原记录。",12,AgentUI.MUTED));
 }
 private void delegate(MaterialCatalog catalog,MaterialCatalog.Entry entry,AgentUI.Screen owner){
  if(closed||suspended||openingDelegate)return;openingDelegate=true;long request=revision;TaskRuntime tasks=TaskRuntime.get(activity);
  tasks.read((state,error)->{openingDelegate=false;if(closed||suspended||request!=revision||!owner.dialog.isShowing())return;
   if(!error.isEmpty()){AgentUI.notice(activity,TaskWorkspace.label(error));return;}
   if(state.saved==null){AgentUI.confirm(activity,"先连接一个 Agent","添加电脑连接后，就可以选择 Agent 并填写基于这份资料的任务要求。",()->AgentConnectionsPage.show(activity));return;}
   TaskWorkspace.delegateMaterial(activity,tasks,state.binding,entry,catalog.account,this::refresh);
  });
 }
 private void export(MaterialCatalog catalog,MaterialCatalog.Entry entry){MaterialDocument.Format[] formats=MaterialDocument.Format.values();String[] labels=new String[formats.length];for(int i=0;i<labels.length;i++)labels[i]=formats[i].label;AlertDialog dialog=AgentUI.alert(activity).setTitle("导出文档到手机").setItems(labels,(choice,which)->MaterialDocumentExport.save(activity,catalog.account,entry,formats[which])).setNegativeButton("取消",null).show();trackSensitive(dialog);}
}
